class Codec {
    // Encodes a tree to a single string.
    func serialize(_ root: TreeNode?) -> String {
        var res: [String] = []
        dfsSerialize(root, &res)
        return res.joined(separator: ",")
    }

    private func dfsSerialize(_ node: TreeNode?, _ res: inout [String]) {
        if node == nil {
            res.append("N")
            return
        }
        res.append(String(node!.val))
        dfsSerialize(node?.left, &res)
        dfsSerialize(node?.right, &res)
    }

    // Decodes your encoded data to tree.
    func deserialize(_ data: String) -> TreeNode? {
        let vals = data.split(separator: ",").map { String($0) }
        var i = 0
        return dfsDeserialize(vals, &i)
    }

    private func dfsDeserialize(_ vals: [String], _ i: inout Int) -> TreeNode? {
        if vals[i] == "N" {
            i += 1
            return nil
        }
        let node = TreeNode(Int(vals[i])!)
        i += 1
        node.left = dfsDeserialize(vals, &i)
        node.right = dfsDeserialize(vals, &i)
        return node
    }
}

