// Definition for a binary tree node.
// #[derive(Debug, PartialEq, Eq)]
// pub struct TreeNode {
//     pub val: i32,
//     pub left: Option<Rc<RefCell<TreeNode>>>,
//     pub right: Option<Rc<RefCell<TreeNode>>>,
// }
//
// impl TreeNode {
//     #[inline]
//     pub fn new(val: i32) -> Self {
//         TreeNode {
//             val,
//             left: None,
//             right: None,
//         }
//     }
// }

use std::cell::RefCell;
use std::rc::Rc;

struct Codec {}

impl Codec {
    fn new() -> Self {
        Codec {}
    }

    fn serialize(&self, root: Option<Rc<RefCell<TreeNode>>>) -> String {
        let mut result = Vec::new();
        self.serialize_dfs(&root, &mut result);
        result.join(",")
    }

    fn serialize_dfs(&self, node: &Option<Rc<RefCell<TreeNode>>>, result: &mut Vec<String>) {
        match node {
            None => result.push("N".to_string()),
            Some(n) => {
                let n_ref = n.borrow();
                result.push(n_ref.val.to_string());
                self.serialize_dfs(&n_ref.left, result);
                self.serialize_dfs(&n_ref.right, result);
            }
        }
    }

    fn deserialize(&self, data: String) -> Option<Rc<RefCell<TreeNode>>> {
        let vals: Vec<&str> = data.split(',').collect();
        let mut index = 0;
        self.deserialize_dfs(&vals, &mut index)
    }

    fn deserialize_dfs(&self, vals: &[&str], index: &mut usize) -> Option<Rc<RefCell<TreeNode>>> {
        if *index >= vals.len() || vals[*index] == "N" {
            *index += 1;
            return None;
        }

        let val: i32 = vals[*index].parse().unwrap();
        *index += 1;

        let node = Rc::new(RefCell::new(TreeNode::new(val)));
        node.borrow_mut().left = self.deserialize_dfs(vals, index);
        node.borrow_mut().right = self.deserialize_dfs(vals, index);

        Some(node)
    }
}

